def test_fish_completion_multiline_help(runner):
    @option(
        "attachment_types",
        "--at",
        "--attachment-type",
        type=(str, str),
        multiple=True,
        help="\b\nAttachment with explicit mimetype,\n--at image.jpg image/jpeg",
    )
    @option("--test-opt", help="A simple test option")
    @Group()
    def cli(attachment_types, test_opt):
        pass

    # Simulate fish completion for 'llm --'
    # The bug causes an error in the fish completion script due to unescaped newlines
    # in the help text. This test asserts that the completion output does not contain
    # the error message "string split: --at image.jpg image/jpeg: unknown option"
    # which indicates the fish script failed to parse the completion output.
    result = runner.invoke(
        cli,
        ["--fish", "completion"],
        env={
            "_CLICK_COMPLETE": "fish_complete",
            "COMP_WORDS": "cli --",
            "COMP_CWORD": "--",
        },
    )

    assert "string split: --at image.jpg image/jpeg: unknown option" not in result.output

import pytest
import click
from click.testing import CliRunner
from click.types import FuncParamType


class MyClass:
    def __init__(self, myvalue: str) -> None:
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_value: str) -> "MyClass":
        if input_value != "works":
            raise ValueError(f"input was {input_value!r}, should be 'works'")
        return MyClass(input_value)


@pytest.fixture
def runner():
    return CliRunner()


def test_func_param_type_value_error_message(runner):
    @click.command()
    @click.argument("mydata", type=FuncParamType(MyClass.from_str))
    def cli(mydata):
        click.echo(f"Success: {mydata.myvalue}")

    result = runner.invoke(cli, ["fails"])
    assert "Error: input was 'fails', should be 'works'" in result.output

from tests.dialects.test_dialect import Validator
import unittest
from sqlglot import parse_one, exp


class TestMysql8225(Validator):
    def test_create_table_auto_increment(self):
        sql = """CREATE TABLE t1(id INT KEY AUTO_INCREMENT);"""
        # The bug causes a ParseError. We assert that it parses without error.
        # The specific AST structure is less important than the fact it parses.
        try:
            parse_one(sql, read="mysql")
        except Exception as e:
            self.fail(f"Parsing CREATE TABLE with AUTO_INCREMENT failed: {e}")
